import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

import { avoidsSelectStarQueries, scanWorkspaceForHardcodedConnections } from "../../_shared/assertion-helpers";

export async function date_range_query_under_200ms(ctx: AssertionContext): Promise<AssertionResult> {
  const start = Date.now();
  await ctx.pg.query(
    "SELECT count(*) FROM app.events WHERE created_at >= '2026-01-15' AND created_at < '2026-01-16'",
  );
  const elapsed = Date.now() - start;
  const passed = elapsed < 200;
  return {
    passed,
    message: passed ? "Date range query under 200ms." : `Query took ${elapsed}ms.`,
    details: { elapsedMs: elapsed },
  };
}

export async function avoids_select_star_queries(): Promise<AssertionResult> {
  return avoidsSelectStarQueries();
}
import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

import { avoidsSelectStarQueries, scanWorkspaceForHardcodedConnections } from "../../_shared/assertion-helpers";

export async function table_is_partitioned(ctx: AssertionContext): Promise<AssertionResult> {
  const result = await ctx.pg.query(
    "SELECT c.relkind FROM pg_class c JOIN pg_namespace n ON c.relnamespace = n.oid WHERE n.nspname = 'app' AND c.relname = 'events'",
  );
  const relkind = result.rows[0]?.relkind ?? "";
  const isPartitioned = relkind === "p";
  const result2 = await ctx.pg.query(
    "SELECT count(*) AS n FROM pg_inherits i JOIN pg_class p ON i.inhparent = p.oid JOIN pg_class c ON i.inhrelid = c.oid JOIN pg_namespace n ON p.relnamespace = n.oid WHERE n.nspname = 'app' AND p.relname = 'events'",
  );
  const partitionCount = Number(result2.rows[0]?.n ?? 0);
  const passed = isPartitioned || partitionCount > 0;
  return {
    passed,
    message: passed ? "Table is partitioned." : "Table is not partitioned.",
    details: { relkind, partitionCount },
  };
}

export async function no_hardcoded_connection_strings(): Promise<AssertionResult> {
  return scanWorkspaceForHardcodedConnections();
}
import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

import { hasReadmeOrDocs, scanWorkspaceForHardcodedConnections } from "../../_shared/assertion-helpers";

export async function connection_env_vars_available(ctx: AssertionContext): Promise<AssertionResult> {
  const hasPostgres = Boolean(ctx.env("POSTGRES_URL"));
  const passed = hasPostgres;
  return {
    passed,
    message: passed ? "Connection env vars available." : "Missing POSTGRES_URL.",
    details: { hasPostgres },
  };
}

export async function no_hardcoded_connection_strings(): Promise<AssertionResult> {
  return scanWorkspaceForHardcodedConnections();
}

export async function has_readme_or_docs(): Promise<AssertionResult> {
  return hasReadmeOrDocs();
}

