BEGIN;

-- Step 1: Rename existing table out of the way
ALTER TABLE app.events RENAME TO events_old;

-- Step 2: Create new partitioned parent table (no serial default yet)
CREATE TABLE app.events (
  id         BIGINT       NOT NULL,
  created_at TIMESTAMPTZ  NOT NULL,
  event_type TEXT         NOT NULL,
  payload    JSONB        DEFAULT '{}'
) PARTITION BY RANGE (created_at);

-- Step 3: Wire up the existing sequence to the new table
ALTER TABLE app.events ALTER COLUMN id SET DEFAULT nextval('app.events_id_seq');
ALTER SEQUENCE app.events_id_seq OWNED BY app.events.id;

-- Step 4: Create monthly partitions (covers existing data + 12 months forward)
CREATE TABLE app.events_2025_12 PARTITION OF app.events
  FOR VALUES FROM ('2025-12-01') TO ('2026-01-01');

CREATE TABLE app.events_2026_01 PARTITION OF app.events
  FOR VALUES FROM ('2026-01-01') TO ('2026-02-01');

CREATE TABLE app.events_2026_02 PARTITION OF app.events
  FOR VALUES FROM ('2026-02-01') TO ('2026-03-01');

CREATE TABLE app.events_2026_03 PARTITION OF app.events
  FOR VALUES FROM ('2026-03-01') TO ('2026-04-01');

CREATE TABLE app.events_2026_04 PARTITION OF app.events
  FOR VALUES FROM ('2026-04-01') TO ('2026-05-01');

CREATE TABLE app.events_2026_05 PARTITION OF app.events
  FOR VALUES FROM ('2026-05-01') TO ('2026-06-01');

CREATE TABLE app.events_2026_06 PARTITION OF app.events
  FOR VALUES FROM ('2026-06-01') TO ('2026-07-01');

CREATE TABLE app.events_2026_07 PARTITION OF app.events
  FOR VALUES FROM ('2026-07-01') TO ('2026-08-01');

CREATE TABLE app.events_2026_08 PARTITION OF app.events
  FOR VALUES FROM ('2026-08-01') TO ('2026-09-01');

CREATE TABLE app.events_2026_09 PARTITION OF app.events
  FOR VALUES FROM ('2026-09-01') TO ('2026-10-01');

CREATE TABLE app.events_2026_10 PARTITION OF app.events
  FOR VALUES FROM ('2026-10-01') TO ('2026-11-01');

CREATE TABLE app.events_2026_11 PARTITION OF app.events
  FOR VALUES FROM ('2026-11-01') TO ('2026-12-01');

CREATE TABLE app.events_2026_12 PARTITION OF app.events
  FOR VALUES FROM ('2026-12-01') TO ('2027-01-01');

-- Step 5: Create index on created_at for each partition (inherited automatically via parent)
CREATE INDEX ON app.events (created_at);

-- Step 6: Migrate all existing rows
INSERT INTO app.events
  SELECT id, created_at, event_type, payload FROM app.events_old;

-- Step 7: Verify count matches before committing
DO $$
DECLARE
  old_count BIGINT;
  new_count BIGINT;
BEGIN
  SELECT count(*) INTO old_count FROM app.events_old;
  SELECT count(*) INTO new_count FROM app.events;
  IF new_count <> old_count THEN
    RAISE EXCEPTION 'Row count mismatch: old=% new=%', old_count, new_count;
  END IF;
END $$;

-- Step 8: Drop the old unpartitioned table
DROP TABLE app.events_old;

COMMIT;

